suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(svglite);library(ragg)})
m<-readRDS(path('metadata/analysis_metadata.rds'));rawri<-rd(path('results/regional_Ri_fractions.tsv'));rawri[,D:=NULL];ri<-merge(m,rawri,by='sample_id');ds<-rd(path('results/differential_summary.tsv'));rm<-rd(path('results/regional_models.tsv'));rt<-rd(path('results/regional_descriptive_tests.tsv'));perf<-rd(path('results/models/performance.tsv'));oof<-merge(rd(path('results/models/participant_mean_OOF.tsv')),m,by='sample_id');repmet<-rd(path('results/models/repeated_metrics.tsv'));clinical<-rd(path('results/clinical/model_trait_associations.tsv'));top<-rd(path('results/representative_genes.tsv'))
FS<-12;LWD<-1.5/72*25.4
theme_pub<-function(){theme_classic(base_family='Arial',base_size=FS)+theme(axis.line=element_line(linewidth=LWD),axis.ticks=element_line(linewidth=LWD),strip.background=element_rect(fill='white',colour='black',linewidth=LWD),strip.text=element_text(size=FS),legend.title=element_blank(),legend.position='bottom',plot.title=element_text(size=FS,face='bold'),axis.text=element_text(size=FS),axis.title=element_text(size=FS),legend.text=element_text(size=FS),plot.subtitle=element_text(size=FS),plot.caption=element_text(size=FS,hjust=0),plot.tag=element_text(size=FS,face='bold'),panel.spacing=grid::unit(3,'mm'))}
fmtp<-function(p)ifelse(is.na(p),'NA',ifelse(p==0,'<2.2e-16',ifelse(p<.001,formatC(p,format='e',digits=1),sprintf('%.3f',p))))
theme_set(theme_pub());pf<-list();registry<-list();source_tables<-list();captions<-list();figure_index<-list()
register<-function(id,data,stats,fn,en,zh){oldenv<-environment(fn);e<-new.env(parent=oldenv);for(v in c('d','st','sd','title','id','cat_value','space','gene','j','metric_value','tt','task_value','ss','grouping_value'))if(exists(v,envir=oldenv,inherits=FALSE))assign(v,get(v,envir=oldenv,inherits=FALSE),e);environment(fn)<-e;registry[[id]]<<-fn;source_tables[[id]]<<-list(data=copy(data),statistics=copy(stats));captions[[id]]<<-list(en=en,zh=zh)}
box<-function(d,value,group='source_group',title=NULL,p=NULL){value_name<-value;group_name<-group;dd<-copy(d);dd[,value:=get(value_name)];dd[,g:=get(group_name)];lev<-if(group_name=='source_group')c('HC','Disease-source')else c(G3,'Core 1 unavailable','Other eligible record');dd[,g:=factor(g,levels=lev)];n<-dd[!is.na(value),.N,by=g];display_groups<-c('Disease-source'='AD + Other','Core 1-positive AD pathology'='AD','Core 1-negative cognitive disorders'='Other');gn<-as.character(n$g);gn[gn%in%names(display_groups)]<-unname(display_groups[gn[gn%in%names(display_groups)]]);labels<-setNames(paste0(gn,'\nn = ',n$N),as.character(n$g));p0<-ggplot(dd,aes(g,value,fill=g,colour=g))+geom_boxplot(width=.55,outlier.shape=NA,alpha=.2,linewidth=LWD)+geom_point(position=position_jitter(width=.16,height=0,seed=SEED),size=1.2,alpha=.65)+scale_fill_manual(values=COL,drop=TRUE)+scale_colour_manual(values=COL,drop=TRUE)+scale_x_discrete(labels=labels)+labs(x=NULL,y=value_name,title=title)+theme_pub()+theme(legend.position='none');if(!is.null(p)){span<-diff(range(dd$value,na.rm=TRUE));hi<-max(dd$value,na.rm=TRUE)+max(span*.1,.01);p0<-p0+annotate('segment',x=1,xend=2,y=hi,yend=hi,linewidth=LWD)+annotate('text',x=1.5,y=hi+max(span*.08,.01),label=paste0('P = ',fmtp(p)),family='Arial',size=FS/ggplot2::.pt)};p0}
volcano<-function(d,title){x<-copy(d);x[,sig:=fcase(FDR<.05&beta>0,'Higher',FDR<.05&beta<0,'Lower',default='Other')];ggplot(x,aes(beta,-log10(pmax(P,.Machine$double.xmin)),colour=sig))+geom_point(size=.65,alpha=.65)+geom_hline(yintercept=-log10(.05),linetype=2,linewidth=LWD)+scale_colour_manual(values=c(Higher='#D55E00',Lower='#0072B2',Other='#B8B8B8'))+labs(x='Adjusted log2 signal difference',y=expression(-log[10](P)),title=title,subtitle=sprintf('Higher %d; lower %d\nTested %d',sum(x$sig=='Higher'),sum(x$sig=='Lower'),nrow(x)))+theme_pub()+theme(legend.position='none')}
forest<-function(d,title=NULL,reference=0,label='region'){label_name<-label;dd<-copy(d);dd[,display_label:=get(label_name)];ggplot(dd,aes(beta,factor(display_label,levels=rev(unique(display_label))),colour=model))+geom_vline(xintercept=reference,linetype=2,linewidth=LWD,colour='#777777')+geom_errorbar(aes(xmin=CI_low,xmax=CI_high),orientation='y',width=.15,linewidth=LWD)+geom_point(size=2)+labs(x='Adjusted effect (95% CI)',y=NULL,title=title)+theme_pub()+theme(legend.position=if(uniqueN(dd$model)>1)'bottom'else'none')}
curves<-rd(path('results/profile/group_curves.tsv'));profile_tests<-rd(path('results/profile/adjusted_tests.tsv'));ptop<-rd(path('results/enrichment/GENE_sensitivity/top5.tsv'))
for(s in SPACES){local({space<-s;d<-ri[region==space];st<-rt[region==space];id<-paste0('Fig1',c('B','C','D','E')[match(space,SPACES)]);register(id,d[,.(sample_id,source_group,Ri)],st,function()box(d,'Ri',title=space,p=st$P)+labs(y='SSB Ri (common GENE reference)'),sprintf('Regional %s Ri calculated from nonredundant within-gene counts. Boxes show median and quartiles; whiskers extend to 1.5 IQR; every point is one participant. Two-sided Wilcoxon P. HC n=144; AD + Other n=117.',space),sprintf('%s区域Ri由基因内非重复计数及共同GENE分母计算。箱体为四分位数，中线为中位数，须线为1.5 IQR范围，点为参与者。双侧Wilcoxon检验；HC 144例，合并疾病组117例。',space))})}
d<-ri[,.(sample_id,source_group,region,fraction)];st<-d[,.(P=wilcox.test(fraction~source_group,exact=FALSE)$p.value),by=region];register('Fig1A',d,st,function(){ggplot(d,aes(fraction,source_group,colour=source_group,fill=source_group))+geom_boxplot(alpha=.2,outlier.shape=NA,width=.5,linewidth=LWD)+geom_point(position=position_jitter(height=.13,width=0,seed=SEED),size=.7,alpha=.5)+facet_wrap(~region,nrow=1,scales='free_x')+scale_colour_manual(values=COL)+scale_fill_manual(values=COL)+labs(x='Fraction of library SSB positions',y=NULL)+theme_pub()+theme(legend.position='none')},'Nonredundant fractions overlapping four annotation classes. Each library position is counted once per class; annotation classes may overlap and fractions do not sum to one.','四区域全局非冗余位点占文库比例；同一位点在每类区域最多计一次，类别之间允许重叠，比例不要求相加为1。')
d<-ri[region=='GENE'];co<-cor.test(d$Ri,d$D,method='spearman',exact=FALSE);st<-data.table(n=nrow(d),rho=unname(co$estimate),P=co$p.value);register('Fig1F',d[,.(sample_id,source_group,Ri,D)],st,function(){ggplot(d,aes(D/1e6,Ri,colour=source_group))+geom_point(size=1.3,alpha=.7)+scale_colour_manual(values=COL)+labs(x='Library SSB positions (millions)',y='GENE Ri',subtitle=sprintf('n = %d; rho = %.5f; %s',st$n,st$rho,if(st$P==0)'P < 2.2e-16'else paste0('P = ',fmtp(st$P))))+theme_pub()},'GENE Ri versus all-valid-BED deduplicated library positions. The two-sided Spearman test uses all 261 participants.','GENE Ri与完整有效BED文库去重位点数的关系；261例参与双侧Spearman分析。')
d<-rm[model%in%c('age_sex','technical')];register('Fig1G',d,d,function(){x<-copy(d);x[,label:=paste(region,ifelse(model=='age_sex','Age/sex','Full adjustment'))];ggplot(x,aes(ratio,factor(label,levels=rev(label)),colour=model))+geom_vline(xintercept=1,linetype=2,linewidth=LWD)+geom_errorbarh(aes(xmin=ratio_low,xmax=ratio_high),height=.2,linewidth=LWD)+geom_point(size=2)+scale_colour_manual(values=c(age_sex='#8A8A8A',technical='#3C5488'),labels=c('Age/sex','Full adjustment'))+labs(x='Ratio of Ri + 1 (95% CI)',y=NULL)+theme_pub()},'Age/sex and fully adjusted disease-source effects on log2(Ri+1), shown as ratios of Ri+1 and 95% CI. Technical adjustment includes log10 library size and poly(A) retention.','年龄性别模型及进一步技术调整模型的来源效应，以Ri+1比值及95%CI显示；技术变量为log10文库位点数和poly(A)保留率。')
for(s in SPACES){local({space<-s;d<-rd(path('results/differential',paste0(space,'__A_primary__Disease_vs_HC.tsv')));id<-paste0('Fig2',LETTERS[match(space,SPACES)]);register(id,d,d,function()volcano(d,space),'Broad disease-source versus HC associations. Colour indicates BH-adjusted P<0.05 within this annotation space; axes use adjusted log2(1+SSB_LPKM) effects and nominal P.','宽泛疾病来源与HC的基因关联；颜色依据区域内BH校正P<0.05，横轴为调整后log信号差值，纵轴为原始P。')})}
shared<-rd(path('results/EXON_shared_unique.tsv'));sd<-data.table(set=c('Positive only','Negative only','Shared, same direction','Direct pathology contrast'),n=c(sum(shared$positive_only),sum(shared$negative_only),sum(shared$shared),sum(shared$direct_associated)));register('Fig2E',sd,shared,function(){ggplot(sd,aes(n,reorder(set,n)))+geom_col(fill='#3C5488',width=.6)+geom_text(aes(label=n),hjust=-.2,size=FS/ggplot2::.pt)+scale_x_continuous(expand=expansion(mult=c(0,.3)))+labs(x='EXON associations',y=NULL)+theme_pub()},'Primary EXON sets defined by the two Core 1-group versus HC comparisons. Shared sets require significance and concordant direction. The direct positive-versus-negative contrast provides the pathology comparison.','两个Core 1组对HC的EXON集合，共享集合要求显著且同向；病理关联由阳性对阴性的直接对比检验。')
d<-ds[model=='B_primary'];register('Fig2F',d,d,function(){x<-melt(d,id.vars=c('region','contrast'),measure.vars=c('higher','lower'),variable.name='direction',value.name='features');ggplot(x,aes(contrast,region,fill=features))+geom_tile(colour='white')+geom_text(aes(label=features),size=FS/ggplot2::.pt)+facet_wrap(~direction,nrow=1)+scale_fill_gradient(low='#F2F2F2',high='#3C5488')+labs(x=NULL,y=NULL)+theme_pub()+scale_x_discrete(labels=c(Positive_vs_HC='Core 1+\nvs HC',Negative_vs_HC='Core 1−\nvs HC',Positive_vs_Negative='Core 1+\nvs Core 1−'))+theme(axis.text.x=element_text(angle=0,hjust=.5))},'Higher and lower feature counts for three predefined Core 1 contrasts in each region. Zero is displayed when no feature passes BH correction.','各区域三个Core 1对比的升高及降低特征数；无发现时显示真实零值。')
d<-rbindlist(lapply(SPACES,function(s){z<-rd(path('results/differential',paste0(s,'__B_primary__Positive_vs_Negative.tsv')));z<-z[order(FDR,-abs(beta),gene_id)][1:3];z[,label:=paste(s,gene_name,sep=': ')];z}));d[,model:='Core 1 positive vs negative'];register('FigS13A',d,d,function()forest(d,label='label')+scale_colour_manual(values='#737373')+labs(x='Pathology contrast: adjusted effect'), 'Representative coefficients from the predefined direct pathology contrast, ranked within region by adjusted P and absolute effect. Display does not imply significance.','各区域按校正P和效应排序的直接病理比较代表系数，显示95%CI；展示本身不代表显著。')
d<-shared[positive_FDR<.05|negative_FDR<.05];d[,association_set:=fcase(shared,'Shared',positive_only,'Core 1+ only',negative_only,'Core 1− only',default='Opposite directions')];st<-data.table(model_n=259,tested=nrow(shared),displayed=nrow(d),shared=sum(d$shared),positive_only=sum(d$positive_only),negative_only=sum(d$negative_only));register('Fig2G',d,st,function()ggplot(d,aes(positive_beta,negative_beta,colour=association_set))+geom_abline(slope=1,intercept=0,linetype=2,colour='#8A8A8A',linewidth=LWD)+geom_hline(yintercept=0,colour='#BBBBBB',linewidth=.25)+geom_vline(xintercept=0,colour='#BBBBBB',linewidth=.25)+geom_point(size=.7,alpha=.65)+scale_colour_manual(values=c('Shared'='#3C5488','Core 1+ only'='#8064A2','Core 1− only'='#E69F00','Opposite directions'='#8A8A8A'))+guides(colour=guide_legend(ncol=2,byrow=TRUE))+labs(x='Core 1+ versus HC effect',y='Core 1− versus HC effect',subtitle='EXON associations against HC')+theme_pub(),'Primary EXON effects for Core 1-positive and negative cognitive-disorder groups versus HC, restricted to genes significant in at least one HC comparison. Colours identify shared concordant or threshold-specific sets. Effects are on log2(1+SSB_LPKM); the diagonal is a visual reference, not an equivalence test. The common model used 259 participants.','在任一对HC比较显著的EXON子集中，对照两种Core 1组的基因效应。颜色区分同向共享及阈值特有集合，效应尺度为log2(1+SSB_LPKM)；对角线是视觉参考，不是等效检验。统一模型使用259例。')
d<-rbindlist(lapply(SPACES,function(s){a<-rd(path('results/differential',paste0(s,'__A_primary__Disease_vs_HC.tsv')));b<-rd(path('results/differential',paste0(s,'__A_unshared__Disease_vs_HC.tsv')));x<-merge(a[FDR<.05,.(gene_id,original_beta=beta)],b[,.(gene_id,beta,FDR)],by='gene_id');data.table(region=s,primary=sum(a$FDR<.05),common=nrow(x),same_direction=sum(sign(x$beta)==sign(x$original_beta)),same_direction_significant=sum(sign(x$beta)==sign(x$original_beta)&x$FDR<.05))}));register('Fig2H',d,d,function(){x<-melt(d,id.vars='region',measure.vars=c('primary','same_direction','same_direction_significant'));ggplot(x,aes(region,value,fill=variable))+geom_col(position='dodge',width=.65)+scale_fill_manual(values=c(primary='#B8B8B8',same_direction='#8064A2',same_direction_significant='#3C5488'),labels=c(primary='Primary',same_direction='Same direction',same_direction_significant='Same direction + significant'))+guides(fill=guide_legend(ncol=1))+labs(x=NULL,y='Associations',fill=NULL)+theme_pub()},'Broad associations and their direction/significance after excluding regions shared between genes. Sensitivity counts use the intersecting tested set.','宽泛关联在排除跨基因共享区域后的方向和显著性保留情况；敏感性数量基于共同受检集合。')
make_profile<-function(d,title){bounds<-cumsum(NB);mid<-bounds-NB/2;ggplot(d,aes(position,mean,colour=group,fill=group))+geom_ribbon(aes(ymin=CI_low,ymax=CI_high),alpha=.15,colour=NA)+geom_line(linewidth=LWD)+geom_vline(xintercept=bounds+.5,colour='#BBBBBB',linewidth=.25)+scale_colour_manual(values=COL,labels=c('HC'='HC','Disease-source'='Disease-source','Core 1-positive AD pathology'='Core 1+ AD pathology','Core 1-negative cognitive disorders'='Core 1− cognitive disorders'))+scale_fill_manual(values=COL,labels=c('HC'='HC','Disease-source'='Disease-source','Core 1-positive AD pathology'='Core 1+ AD pathology','Core 1-negative cognitive disorders'='Core 1− cognitive disorders'))+guides(colour=guide_legend(ncol=2,byrow=TRUE),fill=guide_legend(ncol=2,byrow=TRUE))+scale_x_continuous(breaks=mid,labels=c('Up 5–2k','Up 2–1k','Up 1–0.2k','TSS up','First exon','First intron','Internal exons','Internal introns','Last exon','TES down','Down 0.2–1k','Down 1–2k','Down 2–5k'))+labs(x='Transcript-oriented structural bins (5′ to 3′)',y=if(d$metric[1]=='Ri')'Mean profile Ri'else if(d$metric[1]=='mean_count')'Mean transcript-bin count'else 'SSBs per million annotated bp',title=title)+theme_pub()+theme(axis.text.x=element_text(angle=45,hjust=1))}
d<-curves[grouping=='source_group'&metric=='Ri'];register('Fig3A',d,profile_tests,function()make_profile(d,NULL),'Mean transcript-oriented profile Ri across 13 structural classes and 150 bins. Shading is pointwise 95% CI from 2000 participant bootstrap samples. Transcript annotations retain multiplicity.','13类区域150个bin的转录本方向平均profile Ri；阴影为2000次参与者bootstrap点态95%CI，保留转录本注释累计。')
for(cat in c('Process','Component','RCTM','HPO')){local({cat_value<-cat;id<-paste0('Fig3',c('D','E','F','G')[match(cat_value,c('Process','Component','RCTM','HPO'))]);d<-ptop[set=='All' & category==cat_value];title<-c(Process='GO biological process',Component='GO cellular component',RCTM='Reactome',HPO='Human Phenotype Ontology')[[cat_value]];register(id,d,d,function(){if(!nrow(d))return(ggplot()+annotate('text',x=0,y=0,label='No terms passed adjusted P < 0.05',size=FS/ggplot2::.pt,family='Arial')+labs(title=title)+theme_void(base_family='Arial',base_size=FS));x<-copy(d);x[,term_label:=stringr::str_wrap(description,35)];ggplot(x,aes(-log10(pmax(p_value,.Machine$double.xmin)),reorder(term_label,-fdr),size=number_of_genes))+geom_point(colour='#3C5488')+scale_size_continuous(range=c(2,5))+labs(x=expression(-log[10](P)),y=NULL,title=title,size='Overlapping proteins')+theme_pub()},'GENE sensitivity analysis: up to five terms passing provider-adjusted P<0.05 against the mapped, actually tested GENE background. These do not represent primary EXON enrichment. Point size represents overlapping proteins.','GENE敏感性分析：使用实际受检映射GENE背景的最多5个显著条目，不代表EXON主分析富集；点大小表示重叠蛋白数量。')})}
zmat<-readRDS(path('matrices/EXON_inputs.rds'));ytop<-log2(zmat$lpkm[match(top$gene_id,zmat$annotation$gene_id),m$sample_id,drop=FALSE]+1)
for(k in 1:3){local({j<-k;gene<-top$gene_name[j];d<-copy(m);d[,signal:=ytop[j,match(sample_id,m$sample_id)]];st<-rbindlist(lapply(c('Positive_vs_HC','Negative_vs_HC','Positive_vs_Negative'),function(ct){a<-rd(path('results/differential',paste0('EXON__B_primary__',ct,'.tsv')));a[gene_id==top$gene_id[j]]}));id<-paste0('Fig4A',j);register(id,d[,.(sample_id,pathology_group,signal)],st,function()box(d,'signal',group='pathology_group',title=gene)+labs(y='log2(1 + EXON SSB_LPKM)'), 'Three-group observed EXON signal for a cohort-selected representative feature. HC n=144, AD n=89, Other n=28. Selection used the adjusted pooled contrast; full three-group adjusted coefficients and P values accompany the panel. Boxes show median/IQR, whiskers 1.5 IQR, and every participant. AD denotes author-reviewed Core 1-positive pathology, not a new clinical dementia diagnosis.', '按合并来源主模型排序选出的代表EXON特征。显示HC144、AD89、Other28全部观测点、中位数、IQR及1.5 IQR须线；完整三组调整后系数和P值随图交付。AD表示人工确认的Core 1阳性病理标签，不是重新临床确诊痴呆。')})};rm(zmat)
curve_data<-function(task,type){task_value<-task;ans<-list();for(s in SPACES){d<-oof[task==task_value & region==s];threshold<-sort(unique(c(Inf,d$probability,-Inf)),decreasing=TRUE);z<-rbindlist(lapply(threshold,function(t)data.table(threshold=t,TP=sum(d$y==1&d$probability>=t),FP=sum(d$y==0&d$probability>=t))));z[,`:=`(TPR=TP/sum(d$y==1),FPR=FP/sum(d$y==0),precision=ifelse(TP+FP>0,TP/(TP+FP),1),region=s)];ans[[s]]<-z};rbindlist(ans)}
for(task in c('source','pathology')){local({tt<-task;d<-curve_data(tt,'ROC');st<-perf[task==tt & region%in%SPACES];id<-if(tt=='source')'Fig4B'else'Fig4C';register(id,d,st,function(){labels<-setNames(sprintf('%s %.3f',st$region,st$AUC),st$region);ggplot(d,aes(FPR,TPR,colour=region))+geom_line(linewidth=LWD)+geom_abline(slope=1,intercept=0,linetype=2,linewidth=LWD,colour='#999999')+scale_colour_manual(values=c(GENE='#3C5488',TSS200='#E69F00',INTRON='#8064A2',EXON='#00A087'),labels=labels)+guides(colour=guide_legend(ncol=2,byrow=TRUE))+scale_x_continuous(breaks=c(0,.5,1),limits=c(0,1))+scale_y_continuous(breaks=c(0,.5,1),limits=c(0,1))+labs(x='False-positive rate',y='True-positive rate')+theme_pub()},'ROC curves from participant mean held-out probabilities across five repeated nested CV runs. Each region is an independently trained model.','五次重复嵌套验证的参与者平均折外概率ROC；各区域独立训练。')})}
d<-curve_data('pathology','PR');st<-perf[task=='pathology'&region%in%SPACES];register('Fig4D1',d,st,function(){ggplot(d,aes(TPR,precision,colour=region))+geom_step(linewidth=LWD)+geom_hline(yintercept=st$PR_baseline[1],linetype=2,linewidth=LWD)+scale_colour_manual(values=c(GENE='#3C5488',TSS200='#E69F00',INTRON='#8064A2',EXON='#00A087'))+labs(x='Recall',y='Precision',subtitle=sprintf('Positive fraction baseline: %.3f',st$PR_baseline[1]))+theme_pub()},'Pathology precision–recall curves. The dashed line indicates the positive class fraction in the analyzed cohort.','病理模型PR曲线；虚线为分析队列阳性比例基线。')
