selection<-rbindlist(lapply(SPACES,function(s){x<-rd(path('results/models',paste0('source_',s,'_features.tsv')));a<-rd(path('reference',paste0(s,'_gene_annotation_lengths.tsv')));x<-unique(x[,.(region,gene_id,repetition,outer_fold)]);z<-x[,.N,by=.(region,gene_id)];z<-merge(z,a[,.(gene_id,gene_name)],by='gene_id');z[,`:=`(outer_fits=25L,selection_fraction=N/25)];z}));wr(selection,path('results/models/source_feature_selection_frequency.tsv'));d<-selection[order(-selection_fraction,gene_id),head(.SD,3),by=region];register('FigS10D',d,selection,function()ggplot(d,aes(selection_fraction,reorder(gene_name,selection_fraction)))+geom_col(fill='#3C5488',width=.6)+facet_wrap(~region,scales='free_y',ncol=2)+scale_x_continuous(limits=c(0,1),labels=scales::label_percent())+labs(x='Proportion of 25 outer fits',y=NULL)+theme_pub(),'Three highest-frequency selected features per independent regional source model across 25 outer fits. Selection was learned within training folds. Fits reuse participants; frequencies are stability summaries, not independent biological replicates.','各独立区域来源模型在25个外层训练拟合中选择频率最高的三个特征。选择在训练折内完成；拟合重复使用参与者，频率是稳定性描述，不是独立生物学重复。');supp_layout$S10<-paste0('FigS10',LETTERS[1:4])
