render<-function(p,stem,width,height){dir.create(dirname(stem),recursive=TRUE,showWarnings=FALSE);svglite(paste0(stem,'.svg'),width=width/25.4,height=height/25.4);print(p);dev.off();cairo_pdf(paste0(stem,'.pdf'),width=width/25.4,height=height/25.4,family='Arial');print(p);dev.off();agg_tiff(paste0(stem,'.tiff'),width=width,height=height,units='mm',res=600,compression='lzw');print(p);dev.off();agg_png(paste0(stem,'.png'),width=width,height=height,units='mm',res=180);print(p);dev.off()}
panel_participants<-function(id,dd){
 if(id%in%names(participant_overrides))return(participant_overrides[[id]])
 if(id=='FigS13A')return(m[included_B==TRUE & complete_primary==TRUE,.(sample_id)])
 if(id=='Fig1G')return(m[complete_primary==TRUE,.(sample_id)])
 if(id=='Fig1H')return(m[complete_primary==TRUE,.(sample_id)])
 if(id=='FigS14E')return(m[included_B==TRUE & complete_primary==TRUE,.(sample_id)])
 if(id=='Fig2I')return(rbindlist(lapply(seq_len(nrow(dd)),function(i){x<-rd(path('results/differential',paste0(dd$region[i],'__',dd$model[i],'__participants.tsv')));x[,`:=`(region=dd$region[i],model=dd$model[i])];x})))
 if(id=='Fig3B')return(m[,.(sample_id)])
 if(id=='Fig3C')return(m[complete_primary==TRUE,.(sample_id)])
 if(id=='Fig4F')return(m[source_group=='Disease-source' & complete_primary==TRUE & !is.na(mmse_observed_min),.(sample_id)])
 if(id=='Fig4H')return(unique(oof[task=='source'&region%in%SPACES,.(sample_id)]))
 if(id%in%c('FigS10A','FigS10B','FigS10C'))return(unique(oof[task==if(id=='FigS10B')'pathology'else'source',.(sample_id)]))
 if(id=='FigS10D')return(unique(oof[task=='source'&region%in%SPACES,.(sample_id)]))
 if(grepl('^FigS11',id))return(m[included_C==TRUE & complete_primary==TRUE & stage%in%c('Core1+_AD早期/轻度','Core1+_AD中度及以上'),.(sample_id)])
 if(grepl('^FigS12',id))return(m[complete_primary==TRUE,.(sample_id)])
 if(id=='FigS1A')return(rd(path('metadata/participant_manifest_all315.tsv'))[,.(sample_id)])
 if(id=='FigS1D')return(m[included_C==TRUE,.(sample_id)])
 if(id=='FigS2C')return(data.table(sample_id=character(),analysis_role=character()))
 if(grepl('^FigS3',id))return(m[complete_primary==TRUE,.(sample_id)])
 if(id=='FigS7A')return(unique(oof[task%in%dd$task&region%in%SPACES,.(sample_id,task,region)]))
 if(id%in%c('FigS8B','FigS8C'))return(m[included_B==TRUE,.(sample_id)])
 if(id=='FigS8D')return(m[included_B==TRUE & complete_primary==TRUE,.(sample_id)])
 if(all(c('model','region')%in%names(dd))&&all(grepl('^[AB]_',dd$model))){pairs<-unique(dd[,.(model,region)]);return(rbindlist(lapply(seq_len(nrow(pairs)),function(i){p<-path('results/differential',paste0(pairs$region[i],'__',pairs$model[i],'__participants.tsv'));x<-rd(p);x[,`:=`(model=pairs$model[i],region=pairs$region[i])];x})))}

 if(id%in%c('Fig4B','Fig4C','Fig4D1'))return(unique(oof[task==if(id=='Fig4B')'source'else'pathology',.(sample_id)]))
 if(id=='Fig4D2')return(unique(oof[task%in%c('source','pathology')&region%in%SPACES,.(sample_id,task,region)]))
 if(id=='Fig4G')return(rbindlist(lapply(seq_len(nrow(dd)),function(i){x<-rd(path('results/clinical/participants',paste0('source_Disease_source_',dd$region[i],'_',dd$trait[i],'.tsv')));x[,`:=`(region=dd$region[i],trait=dd$trait[i])];x})))
 if('sample_id'%in%names(dd))return(unique(dd[,.(sample_id)]))
 if(id%in%c('Fig2E','Fig2F','Fig2G'))return(m[complete_primary==TRUE & included_B==TRUE,.(sample_id)])
 if(id%in%c('Fig2H',paste0('Fig2',LETTERS[1:4]),paste0('Fig3',LETTERS[4:7])))return(m[complete_primary==TRUE,.(sample_id)])
 if('n_model'%in%names(dd))return(if(any(grepl('^B_',dd$model)))m[complete_primary==TRUE & included_B==TRUE,.(sample_id)]else m[complete_primary==TRUE,.(sample_id)])
 m[,.(sample_id)]
}
